interface Encoder {
  encode(values: string[]): string;
}
abstract class ExportJob {
  protected abstract createEncoder(): Encoder;
  run(values: string[]) {
    const clean = values.map((value) => value.trim());
    return this.createEncoder().encode(clean);
  }
}
class JsonJob extends ExportJob {
  protected createEncoder(): Encoder {
    return { encode: (values) => JSON.stringify(values) };
  }
}
class PipeJob extends ExportJob {
  protected createEncoder(): Encoder {
    return { encode: (values) => values.join('|') };
  }
}
export function demo() {
  return [new JsonJob().run([' A ', 'B']), new PipeJob().run([' A ', 'B'])];
}

interface Part {
  render(text: string): string;
}
interface DocumentKit {
  heading(): Part;
  paragraph(): Part;
}
class PlainKit implements DocumentKit {
  heading() {
    return { render: (text: string) => text.toUpperCase() };
  }
  paragraph() {
    return { render: (text: string) => text };
  }
}
class MarkdownKit implements DocumentKit {
  heading() {
    return { render: (text: string) => `# ${text}` };
  }
  paragraph() {
    return { render: (text: string) => `> ${text}` };
  }
}
function document(kit: DocumentKit) {
  return [kit.heading().render('Resumo'), kit.paragraph().render('Tudo certo')];
}
export function demo() {
  return [document(new PlainKit()), document(new MarkdownKit())];
}

type Request = { fields: string[]; destination: string };
class ExportBuilder {
  private fields: string[] = [];
  private destination = '';
  select(...fields: string[]) {
    this.fields.push(...fields);
    return this;
  }
  to(destination: string) {
    this.destination = destination;
    return this;
  }
  build(): Request {
    if (!this.fields.length || !this.destination)
      throw new Error('Pedido incompleto');
    const request = { fields: [...this.fields], destination: this.destination };
    this.fields = [];
    this.destination = '';
    return request;
  }
}
export function demo() {
  const builder = new ExportBuilder();
  const first = builder.select('nome', 'email').to('arquivo').build();
  const second = builder.select('id').to('memoria').build();
  return [first, second];
}

class FormTemplate {
  constructor(
    public title: string,
    public fields: { label: string }[],
  ) {}
  clone() {
    return new FormTemplate(
      this.title,
      this.fields.map((field) => ({ ...field })),
    );
  }
}
export function demo() {
  const original = new FormTemplate('Cadastro', [{ label: 'Nome' }]);
  const copy = original.clone();
  copy.title = 'Inscrição';
  copy.fields[0].label = 'Participante';
  return {
    original: original.fields[0].label,
    copy: copy.fields[0].label,
    independent: original.fields !== copy.fields,
  };
}

class Configuration {
  private static instance: Configuration | undefined;
  private constructor(readonly applicationName: string) {}
  static current() {
    return (this.instance ??= new Configuration('Estudos'));
  }
}
export function demo() {
  const first = Configuration.current();
  const second = Configuration.current();
  return { same: first === second, name: second.applicationName };
}

interface Payments {
  charge(cents: number): string;
}
class LegacyGateway {
  bill(decimalAmount: string) {
    return `cobrado:${decimalAmount}`;
  }
}
class PaymentAdapter implements Payments {
  constructor(private gateway: LegacyGateway) {}
  charge(cents: number) {
    if (!Number.isSafeInteger(cents) || cents < 0)
      throw new Error('Centavos inválidos');
    return this.gateway.bill((cents / 100).toFixed(2));
  }
}
export function demo() {
  const payments: Payments = new PaymentAdapter(new LegacyGateway());
  return payments.charge(1590);
}

interface Channel {
  deliver(text: string): string;
}
class Email implements Channel {
  deliver(text: string) {
    return `email:${text}`;
  }
}
class Journal implements Channel {
  deliver(text: string) {
    return `log:${text}`;
  }
}
class Notice {
  constructor(protected channel: Channel) {}
  send(text: string) {
    return this.channel.deliver(text);
  }
}
class UrgentNotice extends Notice {
  override send(text: string) {
    return this.channel.deliver(`URGENTE ${text}`);
  }
}
export function demo() {
  return [
    new Notice(new Email()).send('A'),
    new UrgentNotice(new Journal()).send('B'),
  ];
}

interface Work {
  minutes(): number;
}
class Task implements Work {
  constructor(private duration: number) {}
  minutes() {
    return this.duration;
  }
}
class WorkGroup implements Work {
  constructor(private children: Work[]) {}
  minutes(): number {
    return this.children.reduce((total, child) => total + child.minutes(), 0);
  }
}
export function demo() {
  const preparation = new WorkGroup([new Task(10), new Task(15)]);
  const plan = new WorkGroup([preparation, new Task(20)]);
  return plan.minutes();
}

interface Reader {
  read(): string;
}
class Cached implements Reader {
  private value: string | undefined;
  constructor(private inner: Reader) {}
  read() {
    return (this.value ??= this.inner.read());
  }
}
class Metered implements Reader {
  calls = 0;
  constructor(private inner: Reader) {}
  read() {
    this.calls++;
    return this.inner.read();
  }
}
export function demo() {
  const source = { read: () => 'conteudo' };
  const inside = new Metered(source);
  const cached = new Cached(inside);
  cached.read();
  cached.read();
  const outside = new Metered(new Cached(source));
  outside.read();
  outside.read();
  return { inside: inside.calls, outside: outside.calls };
}

class MaterialStore {
  save(text: string) {
    return { id: 'material-1', text };
  }
}
class SearchIndex {
  indexed: string[] = [];
  add(id: string) {
    this.indexed.push(id);
  }
}
class Publisher {
  constructor(
    private store: MaterialStore,
    private index: SearchIndex,
  ) {}
  publish(text: string) {
    if (!text.trim()) throw new Error('Material vazio');
    const saved = this.store.save(text.trim());
    this.index.add(saved.id);
    return saved.id;
  }
}
export function demo() {
  const index = new SearchIndex();
  const publisher = new Publisher(new MaterialStore(), index);
  return { id: publisher.publish(' Conceito '), indexed: index.indexed };
}

type Style = Readonly<{ sector: string; color: string }>;
class Styles {
  private values = new Map<string, Style>();
  get(sector: string, color: string) {
    const key = JSON.stringify([sector, color]);
    if (!this.values.has(key))
      this.values.set(key, Object.freeze({ sector, color }));
    return this.values.get(key)!;
  }
}
export function demo() {
  const styles = new Styles();
  const a = { row: 1, seat: 1, style: styles.get('A', 'azul') };
  const b = { row: 1, seat: 2, style: styles.get('A', 'azul') };
  return { shared: a.style === b.style, positions: [a.seat, b.seat] };
}

interface Document {
  read(allowed: boolean): string;
}
class ProtectedPreview implements Document {
  private real: { read(): string } | undefined;
  constructor(private create: () => { read(): string }) {}
  read(allowed: boolean) {
    if (!allowed) throw new Error('Acesso negado');
    this.real ??= this.create();
    return this.real.read();
  }
}
export function demo() {
  let loads = 0;
  const preview = new ProtectedPreview(() => {
    loads++;
    return { read: () => 'texto' };
  });
  try {
    preview.read(false);
  } catch {
    /* Rejeição esperada. */
  }
  const deniedLoads = loads;
  preview.read(true);
  preview.read(true);
  return { deniedLoads, loads };
}

abstract class Approval {
  constructor(protected next?: Approval) {}
  abstract approve(amount: number): string;
  protected forward(amount: number) {
    return this.next?.approve(amount) ?? 'sem aprovador';
  }
}
class TeamLead extends Approval {
  approve(amount: number): string {
    return amount <= 100 ? 'lider' : this.forward(amount);
  }
}
class Manager extends Approval {
  approve(amount: number): string {
    return amount <= 1000 ? 'gerente' : this.forward(amount);
  }
}
export function demo() {
  const chain = new TeamLead(new Manager());
  return [chain.approve(50), chain.approve(500), chain.approve(5000)];
}

class Cart {
  quantity = 0;
}
interface Command {
  execute(): void;
  undo(): void;
}
class AddUnits implements Command {
  private previous: number | undefined;
  constructor(
    private cart: Cart,
    private units: number,
  ) {}
  execute() {
    this.previous = this.cart.quantity;
    this.cart.quantity += this.units;
  }
  undo() {
    if (this.previous === undefined) throw new Error('Comando não executado');
    this.cart.quantity = this.previous;
    this.previous = undefined;
  }
}
export function demo() {
  const cart = new Cart();
  const command: Command = new AddUnits(cart, 3);
  command.execute();
  const after = cart.quantity;
  command.undo();
  return { after, undone: cart.quantity };
}

type Lesson = { title: string; children: Lesson[] };
function* depthFirst(node: Lesson): Generator<string> {
  yield node.title;
  for (const child of node.children) yield* depthFirst(child);
}
function* breadthFirst(root: Lesson): Generator<string> {
  const queue = [root];
  for (let index = 0; index < queue.length; index++) {
    const node = queue[index];
    yield node.title;
    queue.push(...node.children);
  }
}
export function demo() {
  const root: Lesson = {
    title: 'A',
    children: [
      { title: 'B', children: [{ title: 'D', children: [] }] },
      { title: 'C', children: [] },
    ],
  };
  return { depth: [...depthFirst(root)], breadth: [...breadthFirst(root)] };
}

class BookingForm {
  private people = 1;
  private capacity = 0;
  canBook = false;
  peopleChanged(value: number) {
    this.people = value;
    this.reconcile();
  }
  roomChanged(capacity: number) {
    this.capacity = capacity;
    this.reconcile();
  }
  private reconcile() {
    this.canBook = this.people > 0 && this.capacity >= this.people;
  }
}
export function demo() {
  const mediator = new BookingForm();
  const peopleInput = { change: (n: number) => mediator.peopleChanged(n) };
  const roomInput = { change: (n: number) => mediator.roomChanged(n) };
  peopleInput.change(5);
  roomInput.change(3);
  const smallRoom = mediator.canBook;
  roomInput.change(8);
  return { smallRoom, largeRoom: mediator.canBook };
}

class ScriptEditor {
  #text = '';
  write(text: string) {
    this.#text = text;
  }
  read() {
    return this.#text;
  }
  checkpoint(): () => void {
    const saved = this.#text;
    return () => {
      this.#text = saved;
    };
  }
}
export function demo() {
  const editor = new ScriptEditor();
  const history: (() => void)[] = [];
  editor.write('Introdução');
  history.push(editor.checkpoint());
  editor.write('Novo final');
  const changed = editor.read();
  history.pop()!();
  return { changed, restored: editor.read() };
}

type Listener = (available: number) => void;
class Vacancies {
  private listeners = new Set<Listener>();
  subscribe(listener: Listener) {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }
  publish(count: number) {
    for (const listener of [...this.listeners]) listener(count);
  }
}
export function demo() {
  const vacancies = new Vacancies();
  const events: string[] = [];
  const unsubscribe = vacancies.subscribe((n) => events.push(`A:${n}`));
  vacancies.subscribe((n) => events.push(`B:${n}`));
  vacancies.publish(1);
  unsubscribe();
  vacancies.publish(2);
  return events;
}

interface AccessState {
  allows(): boolean;
  toggle(): AccessState;
}
class Active implements AccessState {
  allows() {
    return true;
  }
  toggle(): AccessState {
    return new Paused();
  }
}
class Paused implements AccessState {
  allows() {
    return false;
  }
  toggle(): AccessState {
    return new Active();
  }
}
class Subscription {
  private state: AccessState = new Active();
  access() {
    return this.state.allows();
  }
  pauseOrResume() {
    this.state = this.state.toggle();
  }
}
export function demo() {
  const subscription = new Subscription();
  const values = [subscription.access()];
  subscription.pauseOrResume();
  values.push(subscription.access());
  subscription.pauseOrResume();
  values.push(subscription.access());
  return values;
}

type Agent = { name: string; pending: number };
type Routing = (agents: Agent[]) => Agent;
const firstAvailable: Routing = (agents) => agents[0];
const leastLoaded: Routing = (agents) =>
  agents.reduce((a, b) => (a.pending <= b.pending ? a : b));
class TicketRouter {
  constructor(private routing: Routing) {}
  assign(agents: Agent[]) {
    if (!agents.length) throw new Error('Sem agentes');
    return this.routing(agents).name;
  }
}
export function demo() {
  const agents = [
    { name: 'Ana', pending: 4 },
    { name: 'Bia', pending: 1 },
  ];
  return [
    new TicketRouter(firstAvailable).assign(agents),
    new TicketRouter(leastLoaded).assign(agents),
  ];
}

abstract class ContactImporter {
  protected abstract split(input: string): string[];
  run(input: string) {
    const values = this.split(input).map((value) => value.trim());
    return values.filter((value) => value.includes('@'));
  }
}
class LineImporter extends ContactImporter {
  protected split(input: string) {
    return input.split('\n');
  }
}
class SemicolonImporter extends ContactImporter {
  protected split(input: string) {
    return input.split(';');
  }
}
export function demo() {
  return [
    new LineImporter().run(' a@x.test \nsem-email'),
    new SemicolonImporter().run(' b@x.test ;outro'),
  ];
}

interface Visitor {
  text(node: TextFile): number;
  image(node: ImageFile): number;
}
interface File {
  accept(visitor: Visitor): number;
}
class TextFile implements File {
  constructor(readonly characters: number) {}
  accept(visitor: Visitor) {
    return visitor.text(this);
  }
}
class ImageFile implements File {
  constructor(readonly pixels: number) {}
  accept(visitor: Visitor) {
    return visitor.image(this);
  }
}
class StorageEstimate implements Visitor {
  text(node: TextFile) {
    return node.characters * 2;
  }
  image(node: ImageFile) {
    return node.pixels * 4;
  }
}
class FileCount implements Visitor {
  text(_node: TextFile) {
    return 1;
  }
  image(_node: ImageFile) {
    return 1;
  }
}
export function demo() {
  const files: File[] = [new TextFile(10), new ImageFile(5)];
  const sum = (visitor: Visitor) =>
    files.reduce((n, file) => n + file.accept(visitor), 0);
  return {
    estimatedBytes: sum(new StorageEstimate()),
    files: sum(new FileCount()),
  };
}
